# cac_settings: the settings that every Copper and Code app on a board shares.
#
# One file, cac_settings.json, in the flash: /flash/cac_settings.json on boards with a /flash
# folder (STM32), /cac_settings.json on the others (ESP32, RP2350). The Settings app writes it;
# boot.py, the home menu of the board and the other apps read it. It holds up to five WiFi
# networks, and sections of other settings, such as the brightness of the display:
#
#     {"version": 1, "wifi": [{"ssid": "Home", "password": "..."}, ...], "display": {"brightness": 70}}
#
# A section "general" holds the language of the apps, "en" or "it": language(), translator() and
# translate() give each app its texts in it.
#
# The networks are kept from the most recently used. Passwords are in clear text, like in
# MicroPython's own examples: whoever can read the flash can read them.
#
# Copy the same file into every app that uses it (in the IDE: a Python module of the project).
import json
import os
import sys
import time

try:
    import network
except ImportError:                        # the simulator and the PC have no WiFi
    network = None

VERSION = 1
MAX_NETWORKS = 5
TIMEOUT_S = 10                             # for each network tried
DEMO_SCAN = (("Home", -48), ("Office", -61), ("Guest", -75))


def path():
    """Where the file is: in the flash of a board; next to the program on a PC or in the simulator."""
    if sys.platform in ("linux", "darwin", "win32"):
        return "cac_settings.json"
    try:
        if "flash" in os.listdir("/"):
            return "/flash/cac_settings.json"
    except OSError:
        pass
    return "/cac_settings.json"


def load():
    """The settings, or empty ones when the file is missing or broken."""
    try:
        with open(path()) as f:
            data = json.load(f)
    except (OSError, ValueError):
        data = {}
    if not isinstance(data, dict):
        data = {}
    networks = [n for n in data.get("wifi", []) if isinstance(n, dict) and n.get("ssid")]
    data["wifi"] = networks[:MAX_NETWORKS]
    data["version"] = VERSION
    return data


def save(data):
    """Write the settings whole: first a new file, then the rename, so a reset never leaves half."""
    name = path()
    temporary = name + ".new"
    with open(temporary, "w") as f:
        json.dump(data, f)
    try:
        os.remove(name)
    except OSError:
        pass
    os.rename(temporary, name)


def section(name):
    """One section of other settings, such as "display": a dict, empty when there is none."""
    value = load().get(name)
    return value if isinstance(value, dict) else {}


def set_section(name, value):
    """Replace one section; the networks and the other sections stay."""
    data = load()
    data[name] = value
    save(data)


LANGUAGES = ("en", "it")


def language():
    """The language chosen in Settings for every app: "en" or "it", English when none."""
    code = section("general").get("language")
    return code if code in LANGUAGES else "en"


def translator(italian):
    """t(text): the English text, or its Italian from the dict italian when the board speaks Italian."""
    if language() != "it":
        return lambda text: text
    return lambda text: italian.get(text, text)


def translate(ui, italian):
    """The texts of the widgets of ui, written in English in the designer, in the board's language.

    italian maps each English text to its Italian: the text of a label, a button or a checkbox,
    the options of a dropdown or a roller, the placeholder of a text area."""
    if language() != "it":
        return
    import lvgl as lv

    for name in dir(ui):
        o = getattr(ui, name)
        try:
            if isinstance(o, (lv.dropdown, lv.roller)):
                text = italian.get(o.get_options())
                if text is not None:
                    o.set_options(text) if isinstance(o, lv.dropdown) else o.set_options(text, lv.roller.MODE.NORMAL)
            elif isinstance(o, lv.textarea):
                text = italian.get(o.get_placeholder_text())
                if text is not None:
                    o.set_placeholder_text(text)
            elif isinstance(o, (lv.label, lv.checkbox)):
                text = italian.get(o.get_text())
                if text is not None:
                    o.set_text(text)
            elif isinstance(o, lv.button) and o.get_child_count():
                label = o.get_child(0)
                if isinstance(label, lv.label):
                    text = italian.get(label.get_text())
                    if text is not None:
                        label.set_text(text)
        except (AttributeError, TypeError):
            pass


def networks():
    """The saved networks, from the most recently used: a list of {"ssid", "password"}."""
    return load()["wifi"]


def password(ssid):
    for item in networks():
        if item["ssid"] == ssid:
            return item["password"]
    return None


def remember(ssid, password):
    """Save a network, or its new password, as the most recently used; the oldest goes when full."""
    data = load()
    others = [n for n in data["wifi"] if n["ssid"] != ssid]
    data["wifi"] = ([{"ssid": ssid, "password": password}] + others)[:MAX_NETWORKS]
    save(data)


def forget(ssid):
    data = load()
    data["wifi"] = [n for n in data["wifi"] if n["ssid"] != ssid]
    save(data)


def station():
    """The WiFi station interface, active, or None without WiFi hardware."""
    if network is None:
        return None
    try:
        sta = network.WLAN(network.STA_IF)
        sta.active(True)
        return sta
    except (AttributeError, OSError):
        return None


def scan(sta=None):
    """The networks in range, strongest first, as (ssid, rssi); demo names without WiFi hardware."""
    sta = sta or station()
    if sta is None:
        return list(DEMO_SCAN)
    best = {}
    for entry in sta.scan():
        try:
            name = entry[0].decode()
        except ValueError:
            continue
        if name and (name not in best or entry[3] > best[name]):
            best[name] = entry[3]
    return sorted(best.items(), key=lambda item: -item[1])


def connected_ssid(sta=None):
    sta = sta or station()
    if sta is None or not sta.isconnected():
        return None
    try:
        return sta.config("essid")
    except (OSError, ValueError):
        return "?"


def join(ssid, password, sta=None, timeout_s=TIMEOUT_S):
    """Connect to one network; True when connected within timeout_s."""
    sta = sta or station()
    if sta is None:
        return False
    try:
        sta.disconnect()
    except OSError:
        pass
    try:
        sta.connect(ssid, password)
    except OSError as e:
        print("cac_settings: connect", ssid, repr(e))
        return False
    start = time.ticks_ms()
    while not sta.isconnected():
        if time.ticks_diff(time.ticks_ms(), start) > timeout_s * 1000:
            try:
                sta.disconnect()
            except OSError:
                pass
            return False
        time.sleep_ms(100)
    return True


def connect(sta=None, timeout_s=TIMEOUT_S):
    """Connect to the best saved network in range and return its name, or None.

    Already connected: nothing to do. Otherwise the saved networks found by a scan are tried, the
    most recently used first and then by signal; the one that works becomes the most recent.
    Networks that do not answer the scan are not tried: hidden networks are not supported."""
    sta = sta or station()
    if sta is None:
        return None
    current = connected_ssid(sta)
    if current:
        return current
    saved = networks()
    if not saved:
        return None
    try:
        visible = dict(scan(sta))
    except OSError as e:
        print("cac_settings: scan", repr(e))
        return None
    candidates = [n for n in saved if n["ssid"] in visible]
    if len(candidates) > 1:
        first, rest = candidates[0], candidates[1:]
        candidates = [first] + sorted(rest, key=lambda n: -visible[n["ssid"]])
    for item in candidates:
        if join(item["ssid"], item["password"], sta, timeout_s):
            if item is not saved[0]:
                remember(item["ssid"], item["password"])
            print("cac_settings: connected to", item["ssid"], sta.ifconfig()[0])
            return item["ssid"]
    return None

# photo_web: a small web server that takes photos for the Photo Frame from a browser.
#
# The page it serves does the hard part in the browser of a phone or a PC: it opens the photo,
# turns it upright, cuts it to the display, and writes it as an LVGL image in RGB565 with an
# ordered dither, as convert_photos.py does on a PC. The board only receives the finished file
# and writes it to the card, so a photo of a few megabytes from a phone costs it nothing to read.
#
#   server = Server(folder="/sd/photos", pin="4821", port=80, language="en", note=print)
#   server.start()
#   server.poll(budget_ms=15)     # from a timer: it never blocks the screen
#   server.stop()
#
# The page asks the PIN shown on the display with every request but the page itself, so somebody
# else on the same network cannot fill or empty the card. Plain HTTP: use it on your own network.
#
# Requests: GET / (the page), GET /list (the photos and the free space), PUT /photo/NAME.bin (a
# photo, exactly WIDTH x HEIGHT), DELETE /photo/NAME.bin.

import errno
import json
import os
import socket
import time

WIDTH = HEIGHT = 480
HEADER = 12
PHOTO_BYTES = HEADER + WIDTH * HEIGHT * 2
MAGIC, RGB565 = 0x19, 0x12
MAX_HEAD = 4096             # the request line and the headers
CHUNK = 8192
MAX_CLIENTS = 3             # lwIP on the ESP32 has few sockets
IDLE_MS = 20000
NAME_CHARS = "abcdefghijklmnopqrstuvwxyz0123456789_-"
_AGAIN = (errno.EAGAIN, getattr(errno, "EWOULDBLOCK", errno.EAGAIN))
STATUS = {200: "OK", 201: "Created", 400: "Bad Request", 403: "Forbidden", 404: "Not Found",
          405: "Method Not Allowed", 411: "Length Required", 413: "Payload Too Large",
          500: "Internal Server Error", 507: "Insufficient Storage"}


def safe_name(text):
    """NAME.bin from text, with lower-case letters, digits, - and _ only; None if nothing is left."""
    if text.lower().endswith(".bin"):
        text = text[:-4]
    name = "".join(c for c in text.lower() if c in NAME_CHARS)[:40]
    return name + ".bin" if name else None


def _ticks():
    return time.ticks_ms() if hasattr(time, "ticks_ms") else int(time.monotonic() * 1000)


def _elapsed(since):
    return time.ticks_diff(_ticks(), since) if hasattr(time, "ticks_diff") else _ticks() - since


class Client:
    def __init__(self, server, sock):
        self.server = server
        self.sock = sock
        sock.setblocking(False)
        self.head = b""
        self.method = self.path = None
        self.headers = {}
        self.body = b""             # what came with the headers
        self.out = b""
        self.file = None
        self.part = self.target = None
        self.length = self.received = 0
        self.first = b""            # the header of a photo, checked before it is kept
        self.closing = False
        self.closed = False
        self.last = _ticks()

    # --- the connection

    def poll(self):
        """Some work, without waiting; True if something moved."""
        moved = False
        if self.out:
            moved = self._flush()
        elif self.closing:
            self.close()
        elif self.method is None:
            moved = self._read_head()
        elif self.file is not None:
            moved = self._read_body()
        if moved:
            self.last = _ticks()
        elif _elapsed(self.last) > IDLE_MS:
            self.close()
        return moved

    def _recv(self, size):
        try:
            data = self.sock.recv(size)
        except OSError as error:
            if error.args[0] in _AGAIN:
                return None
            self.close()
            return None
        if not data:
            self.close()
        return data

    def _flush(self):
        try:
            n = self.sock.send(self.out[:CHUNK])
        except OSError as error:
            if error.args[0] not in _AGAIN:
                self.close()
            return False
        self.out = self.out[n:]
        if not self.out and self.closing:
            self.close()
        return n > 0

    def close(self):
        if self.closed:
            return
        self.closed = True
        if self.file is not None:   # a photo that did not arrive whole is not kept
            self.file.close()
            self.file = None
            try:
                os.remove(self.part)
            except OSError:
                pass
        try:
            self.sock.close()
        except OSError:
            pass

    def reply(self, code, body=b"", kind="application/json"):
        if isinstance(body, str):
            body = body.encode()
        head = "HTTP/1.0 %d %s\r\nContent-Type: %s\r\nContent-Length: %d\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n" % (code, STATUS.get(code, ""), kind, len(body))
        self.out = head.encode() + body
        self.closing = True

    def error(self, code, text):
        self.reply(code, json.dumps({"error": text}))

    # --- the request

    def _read_head(self):
        data = self._recv(1024)
        if not data:
            return False
        self.head += data
        end = self.head.find(b"\r\n\r\n")
        if end < 0:
            if len(self.head) > MAX_HEAD:
                self.error(400, "headers too long")
            return True
        lines = self.head[:end].decode("utf-8", "replace").split("\r\n")
        self.body = self.head[end + 4:]
        parts = lines[0].split(" ")
        if len(parts) < 2:
            self.error(400, "no request line")
            return True
        self.method, self.path = parts[0].upper(), parts[1]
        for line in lines[1:]:
            if ":" in line:
                key, value = line.split(":", 1)
                self.headers[key.strip().lower()] = value.strip()
        self._route()
        return True

    def _route(self):
        path, _, query = self.path.partition("?")
        if path == "/" and self.method == "GET":
            self.reply(200, self.server.page(), "text/html; charset=utf-8")
            return
        pin = self.headers.get("x-pin", "")
        if not pin:
            for pair in query.split("&"):
                if pair.startswith("pin="):
                    pin = pair[4:]
        if pin != self.server.pin:
            self.error(403, "wrong PIN")
            return
        if path == "/list" and self.method == "GET":
            self.reply(200, json.dumps({"photos": self.server.photos(), "free": self.server.free(), "width": WIDTH, "height": HEIGHT}))
        elif path.startswith("/photo/"):
            name = safe_name(path[7:])
            if name is None:
                self.error(400, "bad name")
            elif self.method == "PUT":
                self._start_photo(name)
            elif self.method == "DELETE":
                self.reply(*self.server.delete(name))
            else:
                self.error(405, "PUT or DELETE")
        else:
            self.error(404, "no such page")

    # --- a photo

    def _start_photo(self, name):
        try:
            self.length = int(self.headers.get("content-length", ""))
        except ValueError:
            self.error(411, "the size is needed")
            return
        if self.length != PHOTO_BYTES:
            self.error(413, "a photo is %d bytes, %dx%d" % (PHOTO_BYTES, WIDTH, HEIGHT))
            return
        if self.server.free() < PHOTO_BYTES + 65536:
            self.error(507, "the card is full")
            return
        self.target = self.server.folder + "/" + name
        self.part = self.target + ".part"
        try:
            self.file = open(self.part, "wb")
        except OSError as error:
            self.error(500, "cannot write: %r" % error)
            return
        body, self.body = self.body, b""
        if body:
            self._write(body)

    def _read_body(self):
        data = self._recv(min(CHUNK, self.length - self.received))
        if not data:
            return False
        self._write(data)
        return True

    def _write(self, data):
        if len(self.first) < HEADER:
            self.first += data[:HEADER - len(self.first)]
            if len(self.first) == HEADER:
                f = self.first
                if f[0] != MAGIC or f[1] != RGB565 or f[4] | f[5] << 8 != WIDTH or f[6] | f[7] << 8 != HEIGHT:
                    self.file.close()
                    self.file = None
                    os.remove(self.part)
                    self.error(400, "not an RGB565 image of %dx%d" % (WIDTH, HEIGHT))
                    return
        try:
            self.file.write(data)
        except OSError as error:
            self.close()
            print("photo_web: write", repr(error))
            return
        self.received += len(data)
        if self.received >= self.length:
            self.file.close()
            self.file = None
            try:
                os.remove(self.target)
            except OSError:
                pass
            os.rename(self.part, self.target)
            self.server.received(self.target)
            self.reply(201, json.dumps({"name": self.target.rsplit("/", 1)[1]}))


class Server:
    def __init__(self, folder="/sd/photos", pin="0000", port=80, language="en", note=None):
        self.folder = folder.rstrip("/")
        self.pin = pin
        self.port = port
        self.language = language
        self.note = note or (lambda text: None)
        self.clients = []
        self.count = 0              # photos received since start
        self._listener = None

    def start(self):
        if self._listener:
            return
        try:
            os.mkdir(self.folder)
        except OSError:
            pass
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listener.bind(socket.getaddrinfo("0.0.0.0", self.port)[0][-1])
            listener.listen(4)
            listener.setblocking(False)
        except OSError:
            listener.close()
            raise
        self._listener = listener

    def stop(self):
        for client in self.clients:
            client.close()
        self.clients = []
        if self._listener:
            self._listener.close()
            self._listener = None

    def running(self):
        return self._listener is not None

    def poll(self, budget_ms=15):
        if not self._listener:
            return
        for _ in range(4):
            try:
                sock, _address = self._listener.accept()
            except OSError:
                break
            if len(self.clients) >= MAX_CLIENTS:
                sock.close()
                continue
            self.clients.append(Client(self, sock))
        start = _ticks()
        while self.clients and _elapsed(start) < budget_ms:
            moved = False
            for client in self.clients:
                if client.poll():
                    moved = True
            self.clients = [c for c in self.clients if not c.closed]
            if not moved:
                break

    # --- the folder

    def photos(self):
        found = []
        try:
            names = sorted(os.listdir(self.folder))
        except OSError:
            names = []
        for name in names:
            if name.lower().endswith(".bin"):
                try:
                    found.append({"name": name, "size": os.stat(self.folder + "/" + name)[6]})
                except OSError:
                    pass
        return found

    def free(self):
        try:
            s = os.statvfs(self.folder)
            return s[0] * s[3]
        except (OSError, AttributeError):
            return 0

    def delete(self, name):
        try:
            os.remove(self.folder + "/" + name)
        except OSError:
            return 404, json.dumps({"error": "no such photo"})
        self.note("deleted " + name)
        return 200, json.dumps({"name": name})

    def received(self, path):
        self.count += 1
        self.note("received " + path.rsplit("/", 1)[1])

    def page(self):
        return PAGE.replace("%LANG%", self.language).replace("%WIDTH%", str(WIDTH)).replace("%HEIGHT%", str(HEIGHT))


PAGE = """<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Photo Frame</title>
<style>
body{font-family:system-ui,sans-serif;background:#0E1621;color:#F2F5F9;margin:0 auto;padding:16px;max-width:640px}
h1{font-size:1.5em;margin:.2em 0}h2{font-size:1.1em;margin:1.4em 0 .4em;color:#93A4B8}
.pick{display:block;background:#4FA3FF;color:#fff;text-align:center;padding:16px;border-radius:8px;font-size:1.2em;cursor:pointer}
.row{display:flex;align-items:center;gap:10px;background:#1B2838;border-radius:6px;padding:8px;margin:6px 0}
.row canvas{width:64px;height:64px;border-radius:4px;flex:none}.row span{flex:1;overflow:hidden;text-overflow:ellipsis}
button{background:#1B2838;color:#F2F5F9;border:1px solid #4A5A70;border-radius:6px;padding:8px 12px;font-size:1em}
.ok{color:#7BD88F}.bad{color:#FF8A7A}small{color:#93A4B8}label{display:block;margin:12px 0}
</style></head><body>
<h1 id="title"></h1><p id="intro"></p>
<label class="pick"><input type="file" id="files" accept="image/*" multiple hidden><span id="pick"></span></label>
<label><input type="checkbox" id="fit"> <span id="fitText"></span></label>
<div id="queue"></div>
<h2 id="onBoard"></h2><small id="free"></small><div id="list"></div>
<script>
const LANG = "%LANG%", W = %WIDTH%, H = %HEIGHT%;
const PIN = new URLSearchParams(location.search).get("pin") || "";
const TEXT = {
 en: {title: "Photo Frame", intro: "Choose photos: this page fits them to the frame and sends them.", pick: "Choose photos",
      fit: "Keep the whole photo, with black bands", onBoard: "On the frame", free: "free on the card",
      converting: "preparing", sending: "sending", done: "on the frame", failed: "not sent: ",
      remove: "Delete", sure: "Delete this photo from the frame?", none: "No photos yet.", pin: "Open this page from the QR code of the frame: the PIN is missing or wrong."},
 it: {title: "Cornice", intro: "Scegli le foto: questa pagina le adatta alla cornice e le invia.", pick: "Scegli le foto",
      fit: "Tieni tutta la foto, con bande nere", onBoard: "Nella cornice", free: "liberi sulla scheda",
      converting: "preparazione", sending: "invio", done: "nella cornice", failed: "non inviata: ",
      remove: "Elimina", sure: "Eliminare questa foto dalla cornice?", none: "Ancora nessuna foto.", pin: "Apri questa pagina dal codice QR della cornice: il PIN manca o non va."}
}[LANG] || null;
const T = TEXT || {};
for (const id of ["title", "intro", "pick", "onBoard"]) document.getElementById(id).textContent = T[id];
document.getElementById("fitText").textContent = T.fit;
document.title = T.title;
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
let names = [];

function api(method, path, body) {
  return fetch(path, {method, body, headers: {"X-Pin": PIN}});
}

function mb(n) { return n >= 1073741824 ? (n / 1073741824).toFixed(1) + " GB" : (n / 1048576).toFixed(0) + " MB"; }

async function refresh() {
  const r = await api("GET", "/list");
  const list = document.getElementById("list");
  if (r.status == 403) { list.textContent = T.pin; list.className = "bad"; return; }
  const data = await r.json();
  names = data.photos.map(p => p.name);
  document.getElementById("free").textContent = mb(data.free) + " " + T.free;
  list.textContent = names.length ? "" : T.none;
  for (const p of data.photos) {
    const row = document.createElement("div"); row.className = "row";
    const label = document.createElement("span"); label.textContent = p.name.replace(/\\.bin$/, "");
    const button = document.createElement("button"); button.textContent = T.remove;
    button.onclick = async () => { if (confirm(T.sure)) { await api("DELETE", "/photo/" + p.name); refresh(); } };
    row.append(label, button); list.append(row);
  }
}

function nameFor(file) {
  let base = file.name.replace(/\\.[^.]*$/, "").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 36) || "photo";
  let name = base + ".bin", n = 2;
  while (names.includes(name)) name = base + "-" + n++ + ".bin";
  names.push(name);
  return name;
}

async function convert(file, fit, canvas) {
  const bitmap = await createImageBitmap(file, {imageOrientation: "from-image"});
  canvas.width = W; canvas.height = H;
  const g = canvas.getContext("2d");
  g.fillStyle = "#000"; g.fillRect(0, 0, W, H);
  const s = fit ? Math.min(W / bitmap.width, H / bitmap.height) : Math.max(W / bitmap.width, H / bitmap.height);
  const w = bitmap.width * s, h = bitmap.height * s;
  g.imageSmoothingQuality = "high";
